namespace Acme.Orders;

public sealed class OrderService(ILogger<OrderService> logger, OrderRepository orders)
{
    public async Task ShipAsync(int orderId, string carrier, CancellationToken ct)
    {
        var order = await orders.FindAsync(orderId, ct);
        if (order is null)
        {
            logger.LogWarning($"Order {orderId} not found");
            return;
        }

        await orders.MarkShippedAsync(order, carrier, ct);
        logger.LogInformation($"Order {orderId} shipped via {carrier}");
    }
}

